  return ret;
}

int board_sc2336_csi_power_acquire(
  FAR struct esp_mipi_csi_config_s *config,
  FAR struct esp_mipi_csi_s **csi)
{
  int ret;

  ret = board_sc2336_csi_get_profile(config);
  if (ret < 0)
    {
      return ret;
    }

  ret = esp_mipi_csi_power_acquire(config, csi);
  if (ret < 0)
    {
      return ret;
    }

  /* Match the ESP-IDF camera baseline: let the MIPI D-PHY LDO settle before
   * configuring the SCCB GPIOs or initializing the I2C controller.
   */

  up_mdelay(BOARD_MIPI_CSI_PHY_SETTLE_MS);
  return OK;
}

int board_sc2336_csi_initialize(FAR struct esp_mipi_csi_s *csi,
  FAR const struct esp_mipi_csi_config_s *config)
{
  return esp_mipi_csi_initialize(csi, config);
}

int board_sc2336_csi_prepare(FAR uint16_t *product_id)
{
  int ret;

  if (product_id == NULL)
    {
      return -EINVAL;
    }

  ret = nxmutex_lock(&g_sc2336_lock);
  if (ret < 0)
    {
      return ret;
    }

  if (g_sc2336_i2c != NULL)
    {
      ret = -EBUSY;
      goto out;
    }

  syslog(LOG_INFO, "SC2336 CSI prepare: stage=i2c_initialize bus=%d\n",
         BOARD_SC2336_I2C_BUS);

  g_sc2336_i2c = esp_i2cbus_initialize(BOARD_SC2336_I2C_BUS);
  if (g_sc2336_i2c == NULL)
    {
      ret = -ENODEV;
      syslog(LOG_ERR,
             "ERROR: SC2336 CSI prepare: stage=i2c_initialize result=%d\n",
             ret);
      goto out;
    }

  syslog(LOG_INFO,
         "SC2336 CSI prepare: stage=i2c_initialize result=%d\n", OK);
  syslog(LOG_INFO,
         "SC2336 CSI prepare: stage=product_id address=0x%02x "
         "frequency=%lu\n", BOARD_SC2336_I2C_ADDRESS,
         (unsigned long)BOARD_SC2336_I2C_FREQUENCY);

  ret = esp32p4_sc2336_probe(g_sc2336_i2c, BOARD_SC2336_I2C_ADDRESS,
                             BOARD_SC2336_I2C_FREQUENCY, product_id);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "ERROR: SC2336 CSI prepare: stage=product_id result=%d\n",
             ret);
      goto errout;
    }

  syslog(LOG_INFO,
         "SC2336 CSI prepare: stage=product_id result=%d product_id=0x%04x\n",
         ret, *product_id);
  syslog(LOG_INFO,
         "SC2336 CSI prepare: stage=profile_configure raw8=%ux%u "
         "lanes=%u dt=0x%02x\n", SC2336_RAW8_WIDTH,
         SC2336_RAW8_HEIGHT, SC2336_RAW8_LANE_NUM,
         SC2336_RAW8_DATA_TYPE);

  ret = esp32p4_sc2336_configure_raw8(g_sc2336_i2c,
                                       BOARD_SC2336_I2C_ADDRESS,
                                       BOARD_SC2336_I2C_FREQUENCY);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "ERROR: SC2336 CSI prepare: stage=profile_configure result=%d\n",
             ret);
      goto errout;
    }

  g_sc2336_configured = true;

  syslog(LOG_INFO,
         "SC2336 CSI prepare: stage=profile_configure result=%d\n", ret);
  syslog(LOG_INFO,
         "SC2336 CSI profile ready: %u lane(s), dt=0x%02x, "
         "%ux%u RAW%u @%u Mbps/lane\n",
         SC2336_RAW8_LANE_NUM, SC2336_RAW8_DATA_TYPE,
         SC2336_RAW8_WIDTH, SC2336_RAW8_HEIGHT,
         SC2336_RAW8_BITS_PER_PIXEL, SC2336_RAW8_LANE_RATE_MBPS);
  ret = OK;
  goto out;

errout:
  board_sc2336_release_locked();
out:
  nxmutex_unlock(&g_sc2336_lock);
  return ret;
}

int board_sc2336_csi_deinitialize(FAR struct esp_mipi_csi_s *csi)
{
  return esp_mipi_csi_deinitialize(csi);
}

int board_sc2336_csi_power_release(FAR struct esp_mipi_csi_s *csi)
{
  return esp_mipi_csi_power_release(csi);
}

int board_sc2336_csi_set_stream(bool enable)
{
  int ret;

  ret = nxmutex_lock(&g_sc2336_lock);
  if (ret < 0)
    {
      return ret;
    }

  if (!g_sc2336_configured || g_sc2336_i2c == NULL)
    {
      ret = -EPIPE;
    }
  else if (g_sc2336_streaming == enable)
    {
      ret = OK;
    }
  else
    {
      ret = esp32p4_sc2336_set_stream(g_sc2336_i2c,
                                       BOARD_SC2336_I2C_ADDRESS,
                                       BOARD_SC2336_I2C_FREQUENCY, enable);
      if (ret >= 0)
        {
          g_sc2336_streaming = enable;
        }
    }

  nxmutex_unlock(&g_sc2336_lock);
  return ret;
}

int board_sc2336_csi_release(void)
{
  int ret;

  ret = nxmutex_lock(&g_sc2336_lock);
  if (ret < 0)
    {
      return ret;
    }

  ret = board_sc2336_release_locked();
  nxmutex_unlock(&g_sc2336_lock);
  return ret;
}

# ESP32-P4 移植开发记录

本文档记录 `esp32p4-function-ev-board` 移植到 openvela Route A 过程中的实际问题、判断和处理结果。

> 状态说明（2026-08-19）：本文是 2026-07-05 的历史排障记录，不是当前
> 构建状态的证明。当前工作树已存在 `esp-hal-3rdparty` 目录，但尚未在本次
> 复核中重新获得完整 build pass 或实板 NSH 日志；继续工作前应按文中构建
> 命令重新执行，并只处理第一个真实错误。

## 2026-07-05：`SPI timing flash clock is invalid`

### 构建命令

```bash
./build.sh contest2026_031_niudanxianqianchong/board/esp32p4/esp32p4-function-ev-board/configs/nsh -j2
```

### 报错现象

```text
In file included from chip/common/espressif/esp_vectors.S:33:
/home/arongw/openvela/nuttx/arch/risc-v/src/chip/esp-hal-3rdparty/nuttx/esp32p4/include/sdkconfig.h:933:4:
error: #error "SPI timing flash clock is invalid"
```

报错发生在 `esp_vectors.S` 编译阶段。`sdkconfig.h` 中对应逻辑会检查是否定义了 flash 频率宏：

```c
CONFIG_ESPRESSIF_FLASH_FREQ_20M
CONFIG_ESPRESSIF_FLASH_FREQ_40M
CONFIG_ESPRESSIF_FLASH_FREQ_80M
```

如果三个宏都没有定义，就会触发：

```c
#error "SPI timing flash clock is invalid"
```

### 原因判断

`nsh/defconfig` 中已经写了：

```ini
CONFIG_ESPRESSIF_FLASH_16M=y
CONFIG_ESPRESSIF_FLASH_FREQ_80M=y
CONFIG_ESPRESSIF_FLASH_MODE_DIO=y
```

但当前 Route A custom chip 下，这些 flash 配置没有正式进入 `nuttx/.config` 和 `nuttx/include/nuttx/config.h`。

之前在 `chips/esp32p4/common/espressif/Make.defs` 中只给 `CFLAGS` 补了宏：

```make
CFLAGS += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_FREQ_80M=1
```

这对 `.c` 文件有效，但这次失败的是 `.S` 汇编预处理文件：

```text
chip/common/espressif/esp_vectors.S
```

`.S` 文件使用 `AFLAGS`，没有拿到只加在 `CFLAGS` 里的 flash 宏，因此 `sdkconfig.h` 仍然认为 flash 频率无效。

### 最小补丁

修改文件：

```text
contest2026_031_niudanxianqianchong/chips/esp32p4/common/espressif/Make.defs
```

将 flash/simple boot 宏抽成公共变量，同时加入 `CFLAGS` 和 `AFLAGS`：

```make
ESPRESSIF_FLASH_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_16M=1
ESPRESSIF_FLASH_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_MODE_DIO=1
ESPRESSIF_FLASH_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_FREQ_80M=1
ESPRESSIF_FLASH_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_SIMPLE_BOOT=1
CFLAGS += $(ESPRESSIF_FLASH_DEFINES)
AFLAGS += $(ESPRESSIF_FLASH_DEFINES)
```

### 验证结果

重新构建后，原错误已经越过：

```text
AS: chip/common/espressif/esp_vectors.S
```

说明 `esp_vectors.S` 已经拿到了 flash 频率宏，`SPI timing flash clock is invalid` 不再出现。

### 新的下一处错误

构建继续向前后，新的第一个真实错误变为：

```text
/home/arongw/openvela/nuttx/arch/risc-v/src/chip/esp-hal-3rdparty/nuttx/esp32p4/include/sdkconfig.h:672:37:
error: 'CONFIG_ESPRESSIF_LOG_LEVEL' undeclared
```

相关定义：

```c
#define CONFIG_BOOTLOADER_LOG_LEVEL CONFIG_ESPRESSIF_LOG_LEVEL
```

这说明 `esp-hal-3rdparty` 的 `sdkconfig.h` 还需要 `CONFIG_ESPRESSIF_LOG_LEVEL`，但当前 Route A 配置链路没有提供该宏。

### 当前结论

本次最小补丁只解决 flash 宏没有传递给汇编文件的问题。它没有试图修复完整 Kconfig 接入。

当前下一步有两个方向：

1. 继续采用最小补丁，在 Make 侧为 `CONFIG_ESPRESSIF_LOG_LEVEL` 提供兜底宏，让 `nsh` build 继续向前推进。
2. 回到 Kconfig 层，把 ESP32-P4 所需的 Espressif common 配置正式接入 `.config`。

当前阶段建议优先使用方向 1，逐个修复构建暴露出的缺失宏；等 `nsh` 能走到更后面，再统一整理 Kconfig。

## 2026-07-05：`CONFIG_ESPRESSIF_LOG_LEVEL` 缺失

### 报错现象

```text
/home/arongw/openvela/nuttx/arch/risc-v/src/chip/esp-hal-3rdparty/nuttx/esp32p4/include/sdkconfig.h:672:37:
error: 'CONFIG_ESPRESSIF_LOG_LEVEL' undeclared
```

相关 include 链路：

```text
chip/common/espressif/esp_start.c
  -> chip/common/espressif/esp_lowputc.h
    -> hal/uart_hal.h
      -> components/log/include/esp_log_level.h
        -> nuttx/esp32p4/include/sdkconfig.h
```

`sdkconfig.h` 中将多个 ESP-IDF log 配置映射到 `CONFIG_ESPRESSIF_LOG_LEVEL`：

```c
#define CONFIG_LOG_DEFAULT_LEVEL CONFIG_ESPRESSIF_LOG_LEVEL
#define CONFIG_LOG_MAXIMUM_LEVEL CONFIG_ESPRESSIF_LOG_LEVEL
#define CONFIG_BOOTLOADER_LOG_LEVEL CONFIG_ESPRESSIF_LOG_LEVEL
```

当前 Route A 配置链路没有把 `CONFIG_ESPRESSIF_LOG_LEVEL` 写入 `nuttx/.config` 或 `nuttx/include/nuttx/config.h`，因此 C 编译时该宏未定义。

### 原因判断

`chips/esp32p4/common/espressif/Kconfig` 中实际有 log level 定义：

```kconfig
config ESPRESSIF_LOG_LEVEL_INFO
config ESPRESSIF_LOG_LEVEL
    int
    default 3 if ESPRESSIF_LOG_LEVEL_INFO
```

其中 `INFO` 对应数值 `3`。

但当前为了避免 Kconfig 重复定义和 choice 冲突，没有完整 source 这份 Espressif common Kconfig。因此 `CONFIG_ESPRESSIF_LOG_LEVEL` 没有进入最终 `.config`。

### 最小补丁

继续沿用 Make 侧兜底方案，并将原来的 `ESPRESSIF_FLASH_DEFINES` 泛化为 `ESPRESSIF_SDKCONFIG_DEFINES`：

```make
ESPRESSIF_SDKCONFIG_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_16M=1
ESPRESSIF_SDKCONFIG_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_MODE_DIO=1
ESPRESSIF_SDKCONFIG_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_FLASH_FREQ_80M=1
ESPRESSIF_SDKCONFIG_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_SIMPLE_BOOT=1
ESPRESSIF_SDKCONFIG_DEFINES += ${DEFINE_PREFIX}CONFIG_ESPRESSIF_LOG_LEVEL=3
CFLAGS += $(ESPRESSIF_SDKCONFIG_DEFINES)
AFLAGS += $(ESPRESSIF_SDKCONFIG_DEFINES)
```

修改文件：

```text
contest2026_031_niudanxianqianchong/chips/esp32p4/common/espressif/Make.defs
```

### 验证结果

重新构建后，`CONFIG_ESPRESSIF_LOG_LEVEL` 报错已经越过。新的第一个真实错误变为：

```text
chip/common/espressif/esp_lowputc.c:355:27:
error: 'CONFIG_ESP_CONSOLE_UART_NUM' undeclared
```

相关代码：

```c
if (uart_num != CONFIG_ESP_CONSOLE_UART_NUM)
```

### 新的下一处问题

`CONFIG_ESP_CONSOLE_UART_NUM` 是 ESP-IDF 风格 console UART 编号宏。当前 `nsh/defconfig` 中启用了：

```ini
CONFIG_UART0_SERIAL_CONSOLE=y
```

`Bootloader.mk` 中也有类似推导逻辑：

```make
$(if $(CONFIG_UART0_SERIAL_CONSOLE),$(call cfg_val,CONFIG_ESP_CONSOLE_UART_NUM,0))
$(if $(CONFIG_UART1_SERIAL_CONSOLE),$(call cfg_val,CONFIG_ESP_CONSOLE_UART_NUM,1))
```

但主编译路径没有得到这个宏，因此 `esp_lowputc.c` 编译失败。

### 当前结论

static void esp_mipi_csi_sample_host_status(
  FAR struct esp_mipi_csi_s *priv)
{
  uint32_t status;
  irqstate_t flags;

  if (priv == NULL || priv->hal.host_dev == NULL)
    {
      return;
    }

  status = priv->hal.host_dev->int_st_main.val;
  flags = spin_lock_irqsave(&priv->irq_lock);
  esp_mipi_csi_count_host_status(priv, status);
  spin_unlock_irqrestore(&priv->irq_lock, flags);
}

static int esp_mipi_csi_dma_interrupt(int irq, FAR void *context,
                                      FAR void *arg)
{
  FAR struct esp_mipi_csi_s *priv = arg;
  uint32_t dma_status;
  uint32_t host_status;
  uint32_t bridge_status;
  irqstate_t flags;

  (void)irq;
  (void)context;

  if (priv == NULL || !priv->running || priv->dma_dev == NULL)
    {
      return OK;
    }

  dma_status = dw_gdma_ll_channel_get_intr_status(
    priv->dma_dev, ESP_MIPI_CSI_DMA_CHANNEL);
  if (dma_status == 0)
    {
      return OK;
    }

  dw_gdma_ll_channel_clear_intr(priv->dma_dev, ESP_MIPI_CSI_DMA_CHANNEL,
                                dma_status);
  host_status = 0;
  bridge_status = 0;
  if ((dma_status & ESP_MIPI_CSI_DMA_DONE_EVENTS) != 0)
    {
      host_status = priv->hal.host_dev->int_st_main.val;
    }

  flags = spin_lock_irqsave(&priv->irq_lock);
  priv->stats.last_dma_status = dma_status;

  if ((dma_status & ESP_MIPI_CSI_DMA_ERROR_EVENTS) != 0)
    {
      priv->stats.dma_error_count++;
      spin_unlock_irqrestore(&priv->irq_lock, flags);
      return OK;
    }

  if ((dma_status & ESP_MIPI_CSI_DMA_DONE_EVENTS) != 0)
    {
      esp_mipi_csi_count_host_status(priv, host_status);
      bridge_status = esp_mipi_csi_get_bridge_errors(priv);
      if (bridge_status != 0)
        {
          esp_mipi_csi_count_bridge_status(priv, bridge_status);
        }

      priv->stats.frame_count++;
    }

  spin_unlock_irqrestore(&priv->irq_lock, flags);

  if ((dma_status & ESP_MIPI_CSI_DMA_DONE_EVENTS) != 0)
    {
      /* The P4 invalidates terminal descriptors after use.  Revalidate the
       * same caller-owned buffer before the next frame arrives.
       */

      dw_gdma_ll_lli_set_block_markers(&priv->dma_lli, false, true, true);
      esp_cache_msync(&priv->dma_lli, sizeof(priv->dma_lli),
                      ESP_CACHE_MSYNC_FLAG_DIR_C2M |
                      ESP_CACHE_MSYNC_FLAG_UNALIGNED);
      dw_gdma_ll_channel_set_link_list_head_addr(
        priv->dma_dev, ESP_MIPI_CSI_DMA_CHANNEL,
        (uint32_t)(uintptr_t)&priv->dma_lli);
      dw_gdma_ll_channel_enable(priv->dma_dev, ESP_MIPI_CSI_DMA_CHANNEL,
                                 true);
      nxsem_post(&priv->frame_sem);
    }

  return OK;
}

static void esp_mipi_csi_disable_interrupts(FAR struct esp_mipi_csi_s *priv)
{
  if (priv->bridge_cpuint >= 0)
    {
      up_disable_irq(ESP_SOURCE2IRQ(ETS_CSI_BRIDGE_INTR_SOURCE));
      esp_teardown_irq(ETS_CSI_BRIDGE_INTR_SOURCE, priv->bridge_cpuint);
      priv->bridge_cpuint = -1;
int esp_mipi_csi_start(FAR struct esp_mipi_csi_s *csi,
                       FAR void *frame_buffer, size_t frame_buffer_bytes)
{
  FAR struct esp_mipi_csi_s *priv = &g_esp_mipi_csi;
  FAR const char *stage;
  int ret;

  if (csi != priv || frame_buffer == NULL)
    {
      return -EINVAL;
    }

  stage = "lock";
  syslog(LOG_INFO,
         "INFO: MIPI-CSI start: stage=begin frame_bytes=%zu\n",
         frame_buffer_bytes);
  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "ERROR: MIPI-CSI start: stage=%s result=%d\n", stage, ret);
      return ret;
    }

  syslog(LOG_INFO, "INFO: MIPI-CSI start: stage=lock result=%d\n", OK);

  stage = "state_check";
  if (!priv->initialized)
    {
      ret = -ESHUTDOWN;
    }
  else if (priv->running)
    {
      ret = -EBUSY;
    }
  else if (frame_buffer_bytes != priv->expected_frame_bytes)
    {
      ret = -EINVAL;
    }
  else
    {
      while (nxsem_trywait(&priv->frame_sem) == OK)
        {
        }

      /* A caller normally clears or initializes its capture buffer before
       * starting a test.  Flush those dirty cache lines before DMA owns the
       * buffer, otherwise a later cache eviction can overwrite received
       * data.
       */

      stage = "frame_buffer_cache_sync";
      syslog(LOG_INFO, "INFO: MIPI-CSI start: stage=%s\n", stage);
      ret = esp_mipi_csi_result(esp_cache_msync(
        frame_buffer, frame_buffer_bytes, ESP_CACHE_MSYNC_FLAG_DIR_C2M |
        ESP_CACHE_MSYNC_FLAG_UNALIGNED));
      if (ret >= 0)
        {
          syslog(LOG_INFO,
                 "INFO: MIPI-CSI start: stage=%s result=%d\n", stage, OK);
          stage = "dma_prepare";
          syslog(LOG_INFO, "INFO: MIPI-CSI start: stage=%s\n", stage);
          ret = esp_mipi_csi_prepare_dma(priv, frame_buffer,
                                         frame_buffer_bytes);
        }

      if (ret >= 0)
        {
          stage = "bridge_enable";
          syslog(LOG_INFO, "INFO: MIPI-CSI start: stage=%s\n", stage);
          priv->running = true;
          mipi_csi_brg_ll_enable(priv->hal.bridge_dev, true);
          syslog(LOG_INFO,
                 "INFO: MIPI-CSI start: stage=complete result=%d\n", OK);
        }
    }

  if (ret < 0)
    {
      syslog(LOG_ERR,
             "ERROR: MIPI-CSI start: stage=%s result=%d\n", stage, ret);
    }

  nxmutex_unlock(&priv->lock);
  return ret;
}

int esp_mipi_csi_wait_frame(FAR struct esp_mipi_csi_s *csi,
                            uint32_t timeout_ms)
{
  FAR struct esp_mipi_csi_s *priv = &g_esp_mipi_csi;
  int ret;

  if (csi != priv || timeout_ms == 0)
    {
      return -EINVAL;
    }

  if (!priv->running)
    {
      return -EPIPE;
    }

  ret = nxsem_tickwait_uninterruptible(&priv->frame_sem,
                                       MSEC2TICK(timeout_ms));
  if (ret < 0)
    {
      esp_mipi_csi_sample_host_status(priv);
      esp_mipi_csi_sample_bridge_errors(priv);
    }

  return ret;
}

int esp_mipi_csi_stop(FAR struct esp_mipi_csi_s *csi)
{
  FAR struct esp_mipi_csi_s *priv = &g_esp_mipi_csi;
  int ret;

  if (csi != priv)
    {
      return -EINVAL;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  if (!priv->initialized)
    {
      ret = -ESHUTDOWN;
    }
  else if (!priv->running)
    {
      ret = -EPIPE;
    }
  else
    {
      mipi_csi_brg_ll_enable(priv->hal.bridge_dev, false);
      priv->running = false;
      esp_mipi_csi_release_dma(priv);
      ret = OK;
    }

  nxmutex_unlock(&priv->lock);
  return ret;
}

int esp_mipi_csi_buffer_sync_for_cpu(FAR void *buffer, size_t bytes)
{
  if (buffer == NULL || bytes == 0)
    {
      return -EINVAL;
    }

  return esp_mipi_csi_result(esp_cache_msync(
    buffer, bytes, ESP_CACHE_MSYNC_FLAG_DIR_M2C |
    ESP_CACHE_MSYNC_FLAG_UNALIGNED));
}

int esp_mipi_csi_get_stats(FAR struct esp_mipi_csi_s *csi,
                           FAR struct esp_mipi_csi_stats_s *stats)
{
  FAR struct esp_mipi_csi_s *priv = &g_esp_mipi_csi;
  irqstate_t flags;

  if (csi != priv || stats == NULL)
    {
      return -EINVAL;
    }

  esp_mipi_csi_sample_bridge_errors(priv);
  flags = spin_lock_irqsave(&priv->irq_lock);
  memcpy(stats, &priv->stats, sizeof(*stats));
  spin_unlock_irqrestore(&priv->irq_lock, flags);
  return OK;
}
