#define CAMERA_TEST_SCCB_SCL_GPIO         8
#define CAMERA_TEST_SCCB_ADDRESS        0x30
#define CAMERA_TEST_SCCB_FREQUENCY   100000
#define CAMERA_TEST_PRODUCT_ID_HIGH  0x3107
#define CAMERA_TEST_PRODUCT_ID_LOW   0x3108
#define CAMERA_TEST_PRODUCT_ID       0xcb3a
#define CAMERA_TEST_STREAM_REG       0x0100
#define CAMERA_TEST_STREAM_OFF       0x00
#define CAMERA_TEST_LDO_CHANNEL          3
#define CAMERA_TEST_LDO_VOLTAGE_MV     2500
#define CAMERA_TEST_RETRY_COUNT           3
#define CAMERA_TEST_RETRY_DELAY_MS       10
#define CAMERA_TEST_I2C_TIMEOUT_MS      100

