    (CAMERA_DISPLAY_WIDTH * CAMERA_DISPLAY_HEIGHT * \
     CAMERA_RGB565_BYTES_PER_PIXEL)

static const char *TAG = "sc2336_camera_test";

static esp_err_t sc2336_read_register(i2c_master_dev_handle_t dev,
                                       uint16_t reg, uint8_t *value)
{
    uint8_t command[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)reg,
    };
    esp_err_t ret = ESP_FAIL;

    for (unsigned int attempt = 1; attempt <= CAMERA_TEST_RETRY_COUNT;
         attempt++) {
        ret = i2c_master_transmit_receive(dev, command, sizeof(command),
                                          value, 1,
                                          CAMERA_TEST_I2C_TIMEOUT_MS);
        if (ret == ESP_OK) {
            return ESP_OK;
        }

        ESP_LOGW(TAG, "SCCB read reg=0x%04x attempt=%u/%u ret=%s",
                 reg, attempt, CAMERA_TEST_RETRY_COUNT,
                 esp_err_to_name(ret));
        vTaskDelay(pdMS_TO_TICKS(CAMERA_TEST_RETRY_DELAY_MS));
    }

    return ret;
}

static esp_err_t sc2336_write_register(i2c_master_dev_handle_t dev,
                                        uint16_t reg, uint8_t value)
{
    uint8_t command[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)reg,
        value,
    };
    esp_err_t ret = ESP_FAIL;

    for (unsigned int attempt = 1; attempt <= CAMERA_TEST_RETRY_COUNT;
         attempt++) {
        ret = i2c_master_transmit(dev, command, sizeof(command),
                                  CAMERA_TEST_I2C_TIMEOUT_MS);
        if (ret == ESP_OK) {
            return ESP_OK;
        }

        ESP_LOGW(TAG, "SCCB write reg=0x%04x value=0x%02x attempt=%u/%u "
                 "ret=%s", reg, value, attempt, CAMERA_TEST_RETRY_COUNT,
                 esp_err_to_name(ret));
        vTaskDelay(pdMS_TO_TICKS(CAMERA_TEST_RETRY_DELAY_MS));
    }

    return ret;
}

static esp_err_t sc2336_read_product_id(i2c_master_dev_handle_t dev,
                                         uint16_t *product_id)
{
    uint8_t id_high = 0;
    uint8_t id_low = 0;
    esp_err_t ret;

    ret = sc2336_read_register(dev, CAMERA_TEST_PRODUCT_ID_HIGH, &id_high);
    if (ret != ESP_OK) {
        return ret;
    }

    ret = sc2336_read_register(dev, CAMERA_TEST_PRODUCT_ID_LOW, &id_low);
    if (ret != ESP_OK) {
        return ret;
    }

    *product_id = ((uint16_t)id_high << 8) | id_low;
    return *product_id == CAMERA_TEST_PRODUCT_ID ? ESP_OK :
           ESP_ERR_INVALID_RESPONSE;
}

static esp_err_t sc2336_run_sccb_baseline(void)
{
    i2c_master_bus_handle_t i2c_bus = NULL;
    i2c_master_dev_handle_t sc2336 = NULL;
    uint16_t first_product_id = 0;
    uint16_t second_product_id = 0;
    esp_err_t ret;

    const i2c_master_bus_config_t i2c_bus_config = {
        .clk_source = I2C_CLK_SRC_DEFAULT,
        .i2c_port = CAMERA_TEST_I2C_PORT,
        .sda_io_num = CAMERA_TEST_SCCB_SDA_GPIO,
        .scl_io_num = CAMERA_TEST_SCCB_SCL_GPIO,
        .flags.enable_internal_pullup = true,
    };
    const i2c_device_config_t sc2336_config = {
        .dev_addr_length = I2C_ADDR_BIT_LEN_7,
        .device_address = CAMERA_TEST_SCCB_ADDRESS,
        .scl_speed_hz = CAMERA_TEST_SCCB_FREQUENCY,
    };

    ESP_LOGI(TAG, "PHASE 1: SCCB read-write-read baseline");
    ret = i2c_new_master_bus(&i2c_bus_config, &i2c_bus);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "I2C master create failed: %s", esp_err_to_name(ret));
        goto out;
    }

    ret = i2c_master_bus_add_device(i2c_bus, &sc2336_config, &sc2336);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "SC2336 I2C device create failed: %s",
                 esp_err_to_name(ret));
        goto out;
    }

    ESP_LOGI(TAG, "TEST: read initial product ID");
    ret = sc2336_read_product_id(sc2336, &first_product_id);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "SC2336 initial product-ID read failed: %s",
                 esp_err_to_name(ret));
        goto out;
    }

    ESP_LOGI(TAG, "PASS: initial product_id=0x%04x", first_product_id);
    ESP_LOGI(TAG, "TEST: write stream-off reg=0x%04x value=0x%02x",
             CAMERA_TEST_STREAM_REG, CAMERA_TEST_STREAM_OFF);
    ret = sc2336_write_register(sc2336, CAMERA_TEST_STREAM_REG,
                                CAMERA_TEST_STREAM_OFF);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "SC2336 stream-off write failed: %s",
                 esp_err_to_name(ret));
        goto out;
    }

    ESP_LOGI(TAG, "PASS: stream-off write acknowledged");
    ESP_LOGI(TAG, "TEST: read product ID after stream-off write");
    ret = sc2336_read_product_id(sc2336, &second_product_id);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "SC2336 post-write product-ID read failed: %s",
                 esp_err_to_name(ret));
        goto out;
    }

    ESP_LOGI(TAG, "PASS: SCCB first=0x%04x second=0x%04x",
             first_product_id, second_product_id);

out:
    if (sc2336 != NULL) {
        esp_err_t remove_ret = i2c_master_bus_rm_device(sc2336);

        if (ret == ESP_OK && remove_ret != ESP_OK) {
            ret = remove_ret;
        }
    }

    if (i2c_bus != NULL) {
        esp_err_t delete_ret = i2c_del_master_bus(i2c_bus);

        if (ret == ESP_OK && delete_ret != ESP_OK) {
            ret = delete_ret;
        }
    }

    return ret;
}

static esp_err_t camera_check_display_memory(void)
{
    size_t spiram_free;
    size_t spiram_largest;

    spiram_free = heap_caps_get_free_size(MALLOC_CAP_SPIRAM | MALLOC_CAP_DMA);
    spiram_largest = heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM |
                                                       MALLOC_CAP_DMA);
    ESP_LOGI(TAG, "DSI frame buffer: need=%u free_spiram_dma=%u "
             "largest_spiram_dma=%u",
             (unsigned int)CAMERA_DISPLAY_FRAME_BYTES,
             (unsigned int)spiram_free, (unsigned int)spiram_largest);

    if (spiram_largest < CAMERA_DISPLAY_FRAME_BYTES) {
        ESP_LOGE(TAG, "DISPLAY SETUP FAILED: 1024x600 RGB565 requires %u "
                 "bytes of DMA-capable PSRAM; enable CONFIG_SPIRAM and "
                 "reconfigure the project", (unsigned int)CAMERA_DISPLAY_FRAME_BYTES);
        return ESP_ERR_NO_MEM;
    }

    return ESP_OK;
}

static bool camera_get_new_frame_buffer(esp_cam_ctlr_handle_t handle,
                                        esp_cam_ctlr_trans_t *trans,
                                        void *user_data)
{
    const esp_cam_ctlr_trans_t *frame = user_data;

    (void)handle;
    trans->buffer = frame->buffer;
    trans->buflen = frame->buflen;
    return false;
}

static bool camera_frame_complete(esp_cam_ctlr_handle_t handle,
                                  esp_cam_ctlr_trans_t *trans,
                                  void *user_data)
{
    (void)handle;
    (void)trans;
    (void)user_data;
    return false;
}

