 ****************************************************************************/

#ifndef __ARCH_RISCV_SRC_ESP32P4_INCLUDE_ESP_MIPI_CSI_H
#define __ARCH_RISCV_SRC_ESP32P4_INCLUDE_ESP_MIPI_CSI_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include <arch/chip/esp_ldo.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define ESP_MIPI_CSI_BUS0                 0
#define ESP_MIPI_CSI_MAX_DATA_LANES        2
#define ESP_MIPI_CSI_DPHY_VOLTAGE_MV    2500

/* CSI-2 data types used by the raw capture path. */

#define ESP_MIPI_CSI_DT_RAW8               0x2a
#define ESP_MIPI_CSI_DT_RAW10              0x2b
#define ESP_MIPI_CSI_DT_RAW12              0x2c

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct esp_mipi_csi_s;

/* This is deliberately a receiver-only primitive.  A board owns sensor
 * reset, MCLK, SCCB and the sensor's stream profile; this layer only accepts
 * the profile's resulting CSI-2 transport parameters.
 */

struct esp_mipi_csi_config_s
{
  uint8_t  lane_num;
  uint8_t  data_type;
  uint8_t  bits_per_pixel;
  uint16_t width;
  uint16_t height;
  uint32_t lane_bit_rate_mbps;
  bool     byte_swap;
  struct esp_ldo_config_s phy_ldo;
};

struct esp_mipi_csi_stats_s
{
  uint32_t frame_count;
  uint32_t dma_error_count;
  uint32_t bridge_overrun_count;
  uint32_t bridge_fifo_overflow_count;
  uint32_t bridge_discard_count;
  uint32_t bridge_frame_size_error_count;
  uint32_t csi_ecc_error_count;
  uint32_t csi_crc_error_count;
  uint32_t csi_phy_error_count;
  uint32_t csi_packet_error_count;
  uint32_t last_dma_status;
  uint32_t last_bridge_status;
  uint32_t last_host_status;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/****************************************************************************
 * Name: esp_mipi_csi_power_acquire
 *
 * Description:
 *   Acquire the ESP32-P4 CSI D-PHY LDO described by config->phy_ldo.  This
 *   is separate from CSI Host initialization so a board can follow the
 *   Espressif camera bring-up order: power the MIPI PHY, configure and start
 *   the sensor, then initialize the CSI receiver.  Only one CSI receiver
 *   exists on ESP32-P4.
 *
 ****************************************************************************/

int esp_mipi_csi_power_acquire(
  FAR const struct esp_mipi_csi_config_s *config,
  FAR struct esp_mipi_csi_s **csi);

/****************************************************************************
 * Name: esp_mipi_csi_initialize
 *
 * Description:
 *   Configure the ESP32-P4 CSI PHY, Host and Bridge for a raw CSI-2 stream.
 *   The caller must acquire power with esp_mipi_csi_power_acquire() first.
 *
 ****************************************************************************/

int esp_mipi_csi_initialize(FAR struct esp_mipi_csi_s *csi,
                            FAR const struct esp_mipi_csi_config_s *config);

/****************************************************************************
 * Name: esp_mipi_csi_deinitialize
 *
 * Description:
 *   Stop a running capture if necessary and release CSI Host, Bridge and DMA
 *   resources.  The D-PHY LDO remains acquired until
 *   esp_mipi_csi_power_release() is called.
 *
 ****************************************************************************/

int esp_mipi_csi_deinitialize(FAR struct esp_mipi_csi_s *csi);

/****************************************************************************
 * Name: esp_mipi_csi_power_release
 *
 * Description:
 *   Release a D-PHY LDO acquired by esp_mipi_csi_power_acquire().  CSI Host
 *   resources must have been deinitialized first.
 *
 ****************************************************************************/

int esp_mipi_csi_power_release(FAR struct esp_mipi_csi_s *csi);

/****************************************************************************
 * Name: esp_mipi_csi_start
 *
 * Description:
 *   Start continuous reception into a caller-owned DMA-capable buffer.  The
 *   same buffer is re-armed at each completed frame; callers that need a
 *   queue of frames will be added by the video upper-half in P3.
 *
 ****************************************************************************/

int esp_mipi_csi_start(FAR struct esp_mipi_csi_s *csi,
                       FAR void *frame_buffer, size_t frame_buffer_bytes);

/****************************************************************************
 * Name: esp_mipi_csi_wait_frame
 *
 * Description:
 *   Wait for one completed DMA frame.  timeout_ms must be non-zero.
 *
 ****************************************************************************/

int esp_mipi_csi_wait_frame(FAR struct esp_mipi_csi_s *csi,
                            uint32_t timeout_ms);

/****************************************************************************
 * Name: esp_mipi_csi_stop
 *
 * Description:
 *   Stop continuous reception.  The caller may then inspect or free its
 *   frame buffer.
 *
 ****************************************************************************/

int esp_mipi_csi_stop(FAR struct esp_mipi_csi_s *csi);

/****************************************************************************
 * Name: esp_mipi_csi_buffer_sync_for_cpu
 *
 * Description:
 *   Invalidate a completed frame before CPU CRC, non-zero checks or file
 *   writes.  The buffer must be the one passed to esp_mipi_csi_start().
 *
 ****************************************************************************/

int esp_mipi_csi_buffer_sync_for_cpu(FAR void *buffer, size_t bytes);

/****************************************************************************
static struct esp_mipi_csi_s g_esp_mipi_csi =
{
  .lock = NXMUTEX_INITIALIZER,
  .irq_lock = SP_UNLOCKED,
  .dma_cpuint = -1,
  .bridge_cpuint = -1,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int esp_mipi_csi_result(esp_err_t result)
{
  if (result == ESP_OK)
    {
      return OK;
    }

  return result < 0 ? result : -EIO;
}

static int esp_mipi_csi_frame_bytes(
  FAR const struct esp_mipi_csi_config_s *config, FAR size_t *bytes)
{
  uint64_t bits;

  if (config->width == 0 || config->height == 0 ||
      config->bits_per_pixel == 0 || bytes == NULL)
    {
      return -EINVAL;
    }

  bits = (uint64_t)config->width * config->height *
         config->bits_per_pixel;
  if ((bits & 7) != 0 || bits / 8 > SIZE_MAX)
    {
      return -EINVAL;
    }

  *bytes = bits / 8;
  return OK;
}

static bool esp_mipi_csi_data_type_valid(uint8_t data_type,
                                         uint8_t bits_per_pixel)
{
  if (data_type == ESP_MIPI_CSI_DT_RAW8)
    {
      return bits_per_pixel == 8;
    }

  if (data_type == ESP_MIPI_CSI_DT_RAW10)
    {
      return bits_per_pixel == 10;
    }

  if (data_type == ESP_MIPI_CSI_DT_RAW12)
    {
      return bits_per_pixel == 12;
    }

  return false;
}

static void esp_mipi_csi_count_host_status(FAR struct esp_mipi_csi_s *priv,
                                            uint32_t status)
{
  if ((status & ESP_MIPI_CSI_HOST_ECC_CORRECTED) != 0)
    {
      priv->stats.csi_ecc_error_count++;
    }

  if ((status & ESP_MIPI_CSI_HOST_CRC_FATAL) != 0)
    {
      priv->stats.csi_crc_error_count++;
    }

  if ((status & ESP_MIPI_CSI_HOST_PHY_FATAL) != 0)
    {
      priv->stats.csi_phy_error_count++;
    }

  if ((status & (ESP_MIPI_CSI_HOST_PACKET_FATAL |
                 ESP_MIPI_CSI_HOST_FRAME_FATAL |
                 ESP_MIPI_CSI_HOST_DATA_ID)) != 0)
    {
      priv->stats.csi_packet_error_count++;
    }

  priv->stats.last_host_status = status;
}

static void esp_mipi_csi_count_bridge_status(FAR struct esp_mipi_csi_s *priv,
                                              uint32_t status)
{
  priv->stats.last_bridge_status = status;

  if ((status & ESP_MIPI_CSI_BRG_OVERRUN) != 0)
    {
      priv->stats.bridge_overrun_count++;
    }

  if ((status & ESP_MIPI_CSI_BRG_FIFO_OVERFLOW) != 0)
    {
      priv->stats.bridge_fifo_overflow_count++;
    }

  if ((status & ESP_MIPI_CSI_BRG_DISCARD) != 0)
    {
      priv->stats.bridge_discard_count++;
    }

  if ((status & (ESP_MIPI_CSI_BRG_FRAME_SIZE_GT |
                 ESP_MIPI_CSI_BRG_FRAME_SIZE_LT)) != 0)
    {
      priv->stats.bridge_frame_size_error_count++;
    }
}

static uint32_t esp_mipi_csi_get_bridge_errors(
  FAR struct esp_mipi_csi_s *priv)
{
  uint32_t status;

  if (priv == NULL || priv->hal.bridge_dev == NULL)
    {
      return 0;
    }

  /* int_st is masked by int_ena.  The temporary single-IRQ path keeps the
   * bridge interrupt disabled, so sample the sticky raw status instead.
   */

  status = priv->hal.bridge_dev->int_raw.val & ESP_MIPI_CSI_BRG_ERROR_EVENTS;
  if (status != 0)
    {
      priv->hal.bridge_dev->int_clr.val = status;
    }

  return status;
}

static void esp_mipi_csi_sample_bridge_errors(
  FAR struct esp_mipi_csi_s *priv)
{
  uint32_t status;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->irq_lock);
  status = esp_mipi_csi_get_bridge_errors(priv);
  if (status != 0)
    {
      esp_mipi_csi_count_bridge_status(priv, status);
    }

  spin_unlock_irqrestore(&priv->irq_lock, flags);
}

static void esp_mipi_csi_sample_host_status(
  FAR struct esp_mipi_csi_s *priv)
{
  uint32_t status;
  irqstate_t flags;

  if (priv == NULL || priv->hal.host_dev == NULL)
    {
      return;
    }

  status = priv->hal.host_dev->int_st_main.val;
  flags = spin_lock_irqsave(&priv->irq_lock);
  esp_mipi_csi_count_host_status(priv, status);
  spin_unlock_irqrestore(&priv->irq_lock, flags);
}

static int esp_mipi_csi_dma_interrupt(int irq, FAR void *context,
                                      FAR void *arg)
{
  FAR struct esp_mipi_csi_s *priv = arg;
  uint32_t dma_status;
  uint32_t host_status;
  uint32_t bridge_status;
  irqstate_t flags;

  (void)irq;
  (void)context;

  if (priv == NULL || !priv->running || priv->dma_dev == NULL)
    {
      return OK;

  priv->powered = true;
  *csi = priv;
  ret = OK;

out:
  if (ret < 0 && ldo_acquired)
    {
      esp_ldo_release(priv->phy_ldo);
      priv->phy_ldo = NULL;
    }

  nxmutex_unlock(&priv->lock);
  return ret;
}

