{
  FAR struct esp_mipi_csi_s *priv = &g_esp_mipi_csi;
  irqstate_t flags;

  if (csi != priv || stats == NULL)
    {
      return -EINVAL;
    }

  esp_mipi_csi_sample_bridge_errors(priv);
  flags = spin_lock_irqsave(&priv->irq_lock);
